package com.sumax.launcher;
import android.app.*; import android.os.*; import android.content.*; import android.content.pm.*; import android.graphics.*; import android.view.*; import android.widget.*;
public class MainActivity extends Activity {
 String[] modes={"Focus","Companion","System"}; int mode=1;
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setGravity(Gravity.CENTER);root.setPadding(24,48,24,48);root.setBackgroundColor(0xff080e20);
 TextView title=new TextView(this);title.setText("S U M A X");title.setTextSize(28);title.setTextColor(0xff75eaff);root.addView(title); AssistantView assistant=new AssistantView(this); root.addView(assistant,new LinearLayout.LayoutParams(-1,0,1.2f));
 View reactor=new View(this){Paint p=new Paint(3); protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(x,y)*.8f; p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(5);p.setColor(0xff35dfff);c.drawCircle(x,y,r,p);c.drawCircle(x,y,r*.72f,p);p.setColor(0xffa28bff);float a=SystemClock.uptimeMillis()%4000/4000f*360;c.drawArc(x-r,y-r,x+r,y+r,a,85,false,p);p.setStyle(Paint.Style.FILL);p.setColor(0xff75eaff);c.drawCircle(x,y,r*.18f,p);postInvalidateDelayed(33);}};
 root.addView(reactor,new LinearLayout.LayoutParams(-1,0,1));TextView status=new TextView(this);status.setTextColor(-1);status.setTextSize(20);status.setText(modes[mode]+" • Ready");root.addView(status); reactor.setOnClickListener(v->assistant.setEmotion(3));
 for(int i=0;i<modes.length;i++){final int n=i;Button btn=new Button(this);btn.setText(modes[i]);btn.setOnClickListener(v->{mode=n;status.setText(modes[n]+" • Ready");assistant.setEmotion(n==0?2:n==1?1:0);});root.addView(btn);}
 Button apps=new Button(this);apps.setText("All apps");apps.setOnClickListener(v->{Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(Intent.CATEGORY_LAUNCHER);java.util.List<ResolveInfo> list=getPackageManager().queryIntentActivities(q,0);list.sort(new ResolveInfo.DisplayNameComparator(getPackageManager()));String[] labels=new String[list.size()];for(int j=0;j<labels.length;j++)labels[j]=list.get(j).loadLabel(getPackageManager()).toString();new AlertDialog.Builder(this).setTitle("Apps").setItems(labels,(d,j)->{ResolveInfo a=list.get(j);Intent launch=new Intent(Intent.ACTION_MAIN);launch.addCategory(Intent.CATEGORY_LAUNCHER);launch.setClassName(a.activityInfo.packageName,a.activityInfo.name);try{startActivity(launch);}catch(Exception e){Toast.makeText(this,"Unable to open app",0).show();}}).show();});root.addView(apps);setContentView(root);}
}
